mapper.select:
SELECT EXISTS (
    SELECT 1 FROM usuarios WHERE EMAIL = #{email}
    AND ID <> #{exceptoId}
)

mapper.delete:
DELETE ur FROM usuario_rol ur
JOIN roles r ON r.ID = ur.ROL
WHERE ur.USUARIO = #{usuario} AND r.NOMBRE = #{rol}

mapper.update:
UPDATE usuarios
SET NOMBRE = #{nombre}, APELLIDO1 = #{apellido1}, APELLIDO2 = #{apellido2}, EMAIL = #{email}
WHERE ID = #{id}

UPDATE usuarios
SET PASSWORD = #{nuevo}
WHERE ID = #{id} AND PASSWORD COLLATE utf8mb4_bin = #{anterior}

UPDATE usuarios
SET TOKEN_EMAIL = #{hashToken}, TOKEN_EMAIL_EXPIRACION = #{expiracion}, EMAIL_PENDIENTE = #{emailPendiente}
WHERE ID = #{id}
